import React, { useState, useEffect, useRef } from 'react';
import styles from './TerminalCursor.module.css';

const TerminalCursor = () => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isRevealing, setIsRevealing] = useState(false);
  const [revealedSpots, setRevealedSpots] = useState([]);
  const [isTouchDevice, setIsTouchDevice] = useState(false);
  const canvasRef = useRef(null);
  const animationRef = useRef(null);

  // Initialize canvas for eraser effect
  useEffect(() => {
    if (isTouchDevice) return;

    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    
    const resizeCanvas = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
      // Redraw existing revealed spots after resize
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      
      revealedSpots.forEach(spot => {
        drawEraserSpot(spot.x, spot.y, spot.radius);
      });
    };

    const drawEraserSpot = (x, y, radius) => {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    return () => {
      window.removeEventListener('resize', resizeCanvas);
      if (animationRef.current) {
        cancelAnimationFrame(animationRef.current);
      }
    };
  }, [revealedSpots, isTouchDevice]);

  // Handle eraser drawing
  useEffect(() => {
    if (isTouchDevice || !canvasRef.current) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    const drawEraserSpot = (x, y, radius) => {
      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(x, y, radius, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalCompositeOperation = 'source-over';
    };

    if (isRevealing && position.x !== 0 && position.y !== 0) {
      const radius = 60; // Eraser size
      drawEraserSpot(position.x, position.y, radius);
      
      setRevealedSpots(prev => [...prev, { 
        x: position.x, 
        y: position.y, 
        radius,
        id: Date.now() + Math.random()
      }]);
    }
  }, [isRevealing, position, isTouchDevice]);

  // Track mouse position and state
  useEffect(() => {
    if ('ontouchstart' in window || navigator.maxTouchPoints > 0) {
      setIsTouchDevice(true);
      return;
    }

    const handleMouseMove = (e) => {
      setPosition({ x: e.clientX, y: e.clientY });
    };

    const handleMouseDown = (e) => {
      if (e.button === 0) { // Left click only
        setIsRevealing(true);
      }
    };

    const handleMouseUp = () => {
      setIsRevealing(false);
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, []);

  if (isTouchDevice) return null;

  return (
    <>
      {/* Hidden layer (revealed content) - sits behind */}
      <div className={styles.revealedContent}>
        <div className={styles.contentWrapper}>
          <h1 className={styles.secretTitle}>✦ YOU FOUND ME ✦</h1>
          <p className={styles.secretText}>
            Behind the surface, something beautiful was hiding.
          </p>
          <div className={styles.secretIcons}>
            <span>⚡</span>
            <span>🎨</span>
            <span>💡</span>
            <span>🚀</span>
          </div>
          <div className={styles.secretGrid}>
            {[...Array(12)].map((_, i) => (
              <div key={i} className={styles.secretCell}></div>
            ))}
          </div>
        </div>
      </div>

      {/* Eraser canvas - reveals the layer behind */}
      <canvas ref={canvasRef} className={styles.eraserCanvas} />

      {/* Custom cursor */}
      <div 
        className={`${styles.eraserCursor} ${isRevealing ? styles.eraserActive : ''}`}
        style={{ left: position.x, top: position.y }}
      >
        <div className={styles.cursorRing}></div>
        <div className={styles.cursorCenter}></div>
        <div className={styles.eraserEffect}>
          <span>⌵</span>
        </div>
      </div>

      {/* Instruction hint */}
      <div className={styles.hint}>
        💡 <strong>Hold click + move</strong> to erase and reveal what's hidden
      </div>
    </>
  );
};

export default TerminalCursor;
